const name = $json.exchange_name;
const website = $json.website;
if (!name || !website) {
  throw new Error('exchange_name and website are required');
}
const slug = name.toLowerCase()
  .replace(/&/g, 'and')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');
const isoDate = new Date().toISOString().slice(0,10); // YYYY-MM-DD
return [{ json: { name, website, slug, isoDate } }];

const dbText = $items(0).json.data;
const db = JSON.parse(dbText);
const { slug, name } = $items(0).json;

const exists = db.exchanges && Object.values(db.exchanges).some(e => e.slug === `/exchanges/${slug}`);
if (exists) {
  throw new Error(`Exchange \"${name}\" already exists as /exchanges/${slug}`);
}
const order = (db.next_orders && db.next_orders.exchanges) || 1;
const ogs = db.crypto_ogs || {};
const posts = db.posts || {};
return [{ json: { db, order, slug, name, website: $items(0).json.website, isoDate: $items(0).json.isoDate, ogs, posts } }];

